    'section.area.ai.body': { en: 'Methods, systems and social consequences.', 'zh-hans': '方法、系统及其社会影响。', 'zh-hant': '方法、系統及其社會影響。', ja: '手法、システム、社会的帰結。', ko: '방법, 시스템과 사회적 결과.', de: 'Methoden, Systeme und gesellschaftliche Folgen.', fr: 'Méthodes, systèmes et conséquences sociales.', es: 'Métodos, sistemas y consecuencias sociales.', ru: 'Методы, системы и социальные последствия.', ar: 'المناهج والنظم والنتائج الاجتماعية.' },
