    'section.area.engineering.body': { en: 'Design, operation and performance in context.', 'zh-hans': '语境中的设计、运行与性能。', 'zh-hant': '語境中的設計、運作與性能。', ja: '文脈の中での設計、運用、性能。', ko: '맥락 속 설계, 운영과 성능.', de: 'Entwurf, Betrieb und Leistung im Kontext.', fr: 'Conception, fonctionnement et performance en contexte.', es: 'Diseño, funcionamiento y rendimiento en contexto.', ru: 'Проектирование, эксплуатация и эффективность в контексте.', ar: 'التصميم والتشغيل والأداء في سياقه.' },
    'section.area.sustainability.title': { en: 'Sustainability', 'zh-hans': '可持续发展', 'zh-hant': '可持續發展', ja: '持続可能性', ko: '지속가능성', de: 'Nachhaltigkeit', fr: 'Durabilité', es: 'Sostenibilidad', ru: 'Устойчивое развитие', ar: 'الاستدامة' },
    'section.area.sustainability.body': { en: 'Evidence for resilient people, institutions and environments.', 'zh-hans': '为具有韧性的人群、制度与环境提供证据。', 'zh-hant': '為具韌性的人群、制度與環境提供證據。', ja: 'レジリエントな人々、制度、環境のためのエビデンス。', ko: '회복력 있는 사람·제도·환경을 위한 근거.', de: 'Evidenz für resiliente Menschen, Institutionen und Umwelten.', fr: 'Des données pour des personnes, institutions et environnements résilients.', es: 'Evidencia para personas, instituciones y entornos resilientes.', ru: 'Доказательства для устойчивых людей, институтов и среды.', ar: 'أدلة من أجل أشخاص ومؤسسات وبيئات قادرة على الصمود.' },
