    'section.area.society.body': { en: 'Policy, ethics and institutions in practice.', 'zh-hans': '实践中的政策、伦理与制度。', 'zh-hant': '實踐中的政策、倫理與制度。', ja: '実践における政策、倫理、制度。', ko: '실천 속 정책, 윤리와 제도.', de: 'Politik, Ethik und Institutionen in der Praxis.', fr: 'Politiques, éthique et institutions en pratique.', es: 'Política, ética e instituciones en la práctica.', ru: 'Политика, этика и институты на практике.', ar: 'السياسات والأخلاقيات والمؤسسات في الممارسة.' },
    'section.area.frontiers.title': { en: 'Interdisciplinary Frontiers', 'zh-hans': '跨学科前沿', 'zh-hant': '跨學科前沿', ja: '学際的フロンティア', ko: '학제 간 프런티어', de: 'Interdisziplinäre Grenzbereiche', fr: 'Frontières interdisciplinaires', es: 'Fronteras interdisciplinarias', ru: 'Междисциплинарные рубежи', ar: 'آفاق متعددة التخصصات' },
    'section.area.frontiers.body': { en: 'Research at boundaries where disciplines meet.', 'zh-hans': '在学科交汇的边界开展研究。', 'zh-hant': '在學科交匯的邊界開展研究。', ja: '分野が交わる境界での研究。', ko: '학문이 만나는 경계에서 이루어지는 연구.', de: 'Forschung an den Grenzen, an denen Disziplinen zusammentreffen.', fr: 'Des recherches aux frontières où les disciplines se rencontrent.', es: 'Investigación en las fronteras donde se encuentran las disciplinas.', ru: 'Исследования на границах взаимодействия дисциплин.', ar: 'بحوث عند الحدود التي تلتقي فيها التخصصات.' },
    'section.about.ctaKicker': { en: 'The Ridgeline programme', 'zh-hans': 'Ridgeline 期刊项目', 'zh-hant': 'Ridgeline 期刊項目', ja: 'Ridgelineプログラム', ko: 'Ridgeline 프로그램', de: 'Das Ridgeline-Programm', fr: 'Le programme Ridgeline', es: 'El programa Ridgeline', ru: 'Программа Ridgeline', ar: 'برنامج Ridgeline' },
    'section.about.ctaTitle': { en: 'Better systems begin with better questions.', 'zh-hans': '更好的系统，始于更好的问题。', 'zh-hant': '更好的系統，始於更好的問題。', ja: 'より良いシステムは、より良い問いから始まる。', ko: '더 나은 시스템은 더 나은 질문에서 시작됩니다.', de: 'Bessere Systeme beginnen mit besseren Fragen.', fr: 'De meilleurs systèmes commencent par de meilleures questions.', es: 'Los sistemas mejores comienzan con mejores preguntas.', ru: 'Лучшие системы начинаются с лучших вопросов.', ar: 'تبدأ الأنظمة الأفضل بأسئلة أفضل.' },
