    'section.journals.pageTitle': { en: 'Ridgeline journals', 'zh-hans': 'Ridgeline 期刊', 'zh-hant': 'Ridgeline 期刊', ja: 'Ridgelineの学術誌', ko: 'Ridgeline 학술지', de: 'Ridgeline-Zeitschriften', fr: 'Revues Ridgeline', es: 'Revistas de Ridgeline', ru: 'Журналы Ridgeline', ar: 'دوريات Ridgeline' },
    'section.journals.pageDescription': { en: 'Explore the Ridgeline journal family across technology, engineering, applied AI, and interdisciplinary systems research.', 'zh-hans': '探索 Ridgeline 期刊群，涵盖技术、工程、应用人工智能与跨学科系统研究。', 'zh-hant': '探索 Ridgeline 期刊群，涵蓋技術、工程、應用人工智能與跨學科系統研究。', ja: 'テクノロジー、工学、応用AI、学際的なシステム研究にわたるRidgelineの学術誌群をご覧ください。', ko: '기술·공학·응용 인공지능과 학제 간 시스템 연구를 아우르는 Ridgeline 학술지군을 살펴보세요.', de: 'Entdecken Sie die Ridgeline-Zeitschriftenfamilie zu Technologie, Ingenieurwesen, angewandter KI und interdisziplinärer Systemforschung.', fr: 'Découvrez la famille de revues Ridgeline en technologie, ingénierie, IA appliquée et recherche interdisciplinaire sur les systèmes.', es: 'Explore la familia de revistas de Ridgeline sobre tecnología, ingeniería, IA aplicada e investigación interdisciplinaria de sistemas.', ru: 'Изучите семейство журналов Ridgeline о технологиях, инженерии, прикладном ИИ и междисциплинарных системных исследованиях.', ar: 'استكشف عائلة دوريات Ridgeline في التكنولوجيا والهندسة والذكاء الاصطناعي التطبيقي وبحوث النظم متعددة التخصصات.' },
    'section.journals.kicker': { en: 'Ridgeline / Panorama Scholarly Group', 'zh-hans': 'Ridgeline / Panorama Scholarly Group', 'zh-hant': 'Ridgeline / Panorama Scholarly Group', ja: 'Ridgeline / Panorama Scholarly Group', ko: 'Ridgeline / Panorama Scholarly Group', de: 'Ridgeline / Panorama Scholarly Group', fr: 'Ridgeline / Panorama Scholarly Group', es: 'Ridgeline / Panorama Scholarly Group', ru: 'Ridgeline / Panorama Scholarly Group', ar: 'Ridgeline / Panorama Scholarly Group' },
    'section.journals.title': { en: 'Advancing technology. Shaping what comes next.', 'zh-hans': '推动技术进步，塑造未来。', 'zh-hant': '推動技術進步，塑造未來。', ja: 'テクノロジーを前へ。次の時代を形づくる。', ko: '기술을 발전시키고 다음을 만들어 갑니다.', de: 'Technologie voranbringen. Das Kommende gestalten.', fr: 'Faire progresser les technologies. Façonner ce qui vient.', es: 'Impulsar la tecnología. Dar forma a lo que sigue.', ru: 'Развиваем технологии. Формируем будущее.', ar: 'نطوّر التكنولوجيا. ونشكّل ما يأتي.' },
    'section.journals.lede': { en: 'Explore independent journals advancing research across technology, engineering, applied AI, and the systems shaping our shared future.', 'zh-hans': '探索推动技术、工程、应用人工智能及塑造共同未来的系统研究的独立期刊。', 'zh-hant': '探索推動技術、工程、應用人工智能及塑造共同未來的系統研究的獨立期刊。', ja: 'テクノロジー、工学、応用AI、共有する未来を形づくるシステムの研究を前進させる独立した学術誌をご覧ください。', ko: '기술·공학·응용 인공지능과 공동의 미래를 형성하는 시스템 연구를 발전시키는 독립 학술지를 살펴보세요.', de: 'Entdecken Sie unabhängige Zeitschriften, die Forschung zu Technologie, Ingenieurwesen, angewandter KI und den Systemen voranbringen, die unsere gemeinsame Zukunft prägen.', fr: 'Découvrez des revues indépendantes qui font progresser les recherches en technologie, ingénierie, IA appliquée et sur les systèmes qui façonnent notre avenir commun.', es: 'Explore revistas independientes que impulsan la investigación sobre tecnología, ingeniería, IA aplicada y los sistemas que configuran nuestro futuro compartido.', ru: 'Изучите независимые журналы, развивающие исследования технологий, инженерии, прикладного ИИ и систем, формирующих наше общее будущее.', ar: 'استكشف دوريات مستقلة تطوّر البحث في التكنولوجيا والهندسة والذكاء الاصطناعي التطبيقي والنظم التي تشكّل مستقبلنا المشترك.' },
