    'field.translational.body': { en: 'Bridging science and real-world change.', 'zh-hans': '连接科学与现实改变。', 'zh-hant': '連結科學與現實改變。', ja: '科学と現実の変化をつなぐ。', ko: '과학과 현실의 변화를 연결합니다.', de: 'Wissenschaft und Veränderung in der Welt verbinden.', fr: 'Relier la science et le changement concret.', es: 'Conectar la ciencia con el cambio real.', ru: 'Соединяем науку с реальными изменениями.', ar: 'ربط العلم بالتغيير الواقعي.' },
