    seeJournalWebsite: { en: 'See journal website', 'zh-hans': '查看期刊网站', 'zh-hant': '查看期刊網站', ja: '学術誌サイトを見る', ko: '학술지 웹사이트 보기', de: 'Zur Zeitschriftenwebsite', fr: 'Voir le site de la revue', es: 'Ver el sitio de la revista', ru: 'Перейти на сайт журнала', ar: 'عرض موقع الدورية' },
    visitJournal: { en: 'Visit journal website', 'zh-hans': '访问期刊网站', 'zh-hant': '訪問期刊網站', ja: '学術誌サイトへ', ko: '학술지 웹사이트 방문', de: 'Zeitschriftenwebsite besuchen', fr: 'Visiter le site de la revue', es: 'Visitar el sitio de la revista', ru: 'Посетить сайт журнала', ar: 'زيارة موقع الدورية' },
    license: { en: 'License', 'zh-hans': '许可协议', 'zh-hant': '授權協議', ja: 'ライセンス', ko: '라이선스', de: 'Lizenz', fr: 'Licence', es: 'Licencia', ru: 'Лицензия', ar: 'الترخيص' },
    licensePending: { en: 'To be confirmed', 'zh-hans': '待确认', 'zh-hant': '待確認', ja: '確認中', ko: '확인 중', de: 'Noch zu bestätigen', fr: 'À confirmer', es: 'Pendiente de confirmación', ru: 'Требует подтверждения', ar: 'قيد التأكيد' },
    licenseArticleLevel: { en: 'Article-level notice applies', 'zh-hans': '以文章页面所载许可为准', 'zh-hant': '以文章頁面所載授權為準', ja: '記事ごとの表示が適用されます', ko: '개별 논문 고지가 적용됩니다', de: 'Maßgeblich ist der Hinweis am Artikel', fr: 'La mention propre à l’article fait foi', es: 'Prevalece la indicación del artículo', ru: 'Действует указание на странице статьи', ar: 'يسري الإشعار الخاص بالمقالة' },
