    licenseArticleLevel: { en: 'Article-level notice applies', 'zh-hans': '以文章页面所载许可为准', 'zh-hant': '以文章頁面所載授權為準', ja: '記事ごとの表示が適用されます', ko: '개별 논문 고지가 적용됩니다', de: 'Maßgeblich ist der Hinweis am Artikel', fr: 'La mention propre à l’article fait foi', es: 'Prevalece la indicación del artículo', ru: 'Действует указание на странице статьи', ar: 'يسري الإشعار الخاص بالمقالة' },
