    'journal.jlpcs.label': { en: 'Law, psychology & communication', 'zh-hans': '法律、心理学与传播', 'zh-hant': '法律、心理學與傳播', ja: '法・心理学・コミュニケーション', ko: '법·심리학·커뮤니케이션', de: 'Recht, Psychologie & Kommunikation', fr: 'Droit, psychologie et communication', es: 'Derecho, psicología y comunicación', ru: 'Право, психология и коммуникация', ar: 'القانون وعلم النفس والاتصال' },
    'journal.jlpcs.summary': { en: 'Research at the intersection of law, psychology, communication, digital governance, and institutional practice.', 'zh-hans': '研究法律、心理学、传播、数字治理与制度实践的交汇领域。', 'zh-hant': '研究法律、心理學、傳播、數碼治理與制度實踐的交匯領域。', ja: '法、心理学、コミュニケーション、デジタル・ガバナンス、制度実践の交差点にある研究。', ko: '법·심리학·커뮤니케이션·디지털 거버넌스·제도 실천의 교차점에 관한 연구.', de: 'Forschung an der Schnittstelle von Recht, Psychologie, Kommunikation, digitaler Governance und institutioneller Praxis.', fr: 'Recherches à l’intersection du droit, de la psychologie, de la communication, de la gouvernance numérique et des pratiques institutionnelles.', es: 'Investigación en la intersección del derecho, la psicología, la comunicación, la gobernanza digital y la práctica institucional.', ru: 'Исследования на пересечении права, психологии, коммуникации, цифрового управления и институциональной практики.', ar: 'بحوث عند تقاطع القانون وعلم النفس والاتصال والحوكمة الرقمية والممارسة المؤسسية.' },
    'journal.cropt.label': { en: 'Political thought', 'zh-hans': '政治思想', 'zh-hant': '政治思想', ja: '政治思想', ko: '정치사상', de: 'Politisches Denken', fr: 'Pensée politique', es: 'Pensamiento político', ru: 'Политическая мысль', ar: 'الفكر السياسي' },
    'journal.cropt.summary': { en: 'Critical inquiry into political ideas, institutions, intellectual history, and democratic life.', 'zh-hans': '批判性研究政治思想、制度、思想史与民主生活。', 'zh-hant': '批判性研究政治思想、制度、思想史與民主生活。', ja: '政治思想、制度、知性史、民主生活への批判的探究。', ko: '정치적 사상·제도·지성사·민주적 삶에 대한 비판적 탐구.', de: 'Kritische Untersuchungen zu politischen Ideen, Institutionen, Geistesgeschichte und demokratischem Leben.', fr: 'Une réflexion critique sur les idées politiques, les institutions, l’histoire intellectuelle et la vie démocratique.', es: 'Indagación crítica sobre ideas políticas, instituciones, historia intelectual y vida democrática.', ru: 'Критическое исследование политических идей, институтов, интеллектуальной истории и демократической жизни.', ar: 'بحث نقدي في الأفكار السياسية والمؤسسات والتاريخ الفكري والحياة الديمقراطية.' },
    'journal.ggsr.label': { en: 'Global governance', 'zh-hans': '全球治理', 'zh-hant': '全球治理', ja: 'グローバル・ガバナンス', ko: '글로벌 거버넌스', de: 'Globale Governance', fr: 'Gouvernance mondiale', es: 'Gobernanza global', ru: 'Глобальное управление', ar: 'الحوكمة العالمية' },
    'journal.ggsr.summary': { en: 'Research on international institutions, global cooperation, and the systems that connect public life.', 'zh-hans': '研究国际制度、全球合作与连接公共生活的系统。', 'zh-hant': '研究國際制度、全球合作與連結公共生活的系統。', ja: '国際制度、グローバルな協力、公共生活をつなぐシステムに関する研究。', ko: '국제 제도, 글로벌 협력과 공적 삶을 연결하는 시스템에 관한 연구.', de: 'Forschung zu internationalen Institutionen, globaler Zusammenarbeit und den Systemen, die das öffentliche Leben verbinden.', fr: 'Recherches sur les institutions internationales, la coopération mondiale et les systèmes qui relient la vie publique.', es: 'Investigación sobre instituciones internacionales, cooperación global y los sistemas que conectan la vida pública.', ru: 'Исследования международных институтов, глобального сотрудничества и систем, связывающих общественную жизнь.', ar: 'بحوث حول المؤسسات الدولية والتعاون العالمي والنظم التي تربط الحياة العامة.' },
    'journal.jpoii.label': { en: 'Public oversight', 'zh-hans': '公共监督', 'zh-hant': '公共監督', ja: '公共監督', ko: '공공 감독', de: 'Öffentliche Aufsicht', fr: 'Contrôle public', es: 'Supervisión pública', ru: 'Общественный надзор', ar: 'الرقابة العامة' },
    'journal.jpoii.summary': { en: 'Research on accountability, transparency, and the integrity of public institutions.', 'zh-hans': '研究公共机构的问责、透明度与制度完整性。', 'zh-hant': '研究公共機構的問責、透明度與制度完整性。', ja: '公共機関の説明責任、透明性、制度的健全性に関する研究。', ko: '공공기관의 책임성·투명성·제도적 온전성에 관한 연구.', de: 'Forschung zu Rechenschaft, Transparenz und Integrität öffentlicher Institutionen.', fr: 'Recherches sur la responsabilité, la transparence et l’intégrité des institutions publiques.', es: 'Investigación sobre rendición de cuentas, transparencia e integridad de las instituciones públicas.', ru: 'Исследования подотчётности, прозрачности и целостности государственных институтов.', ar: 'بحوث حول المساءلة والشفافية ونزاهة المؤسسات العامة.' },
