    'field.education.note': { en: 'Equity & opportunity', 'zh-hans': '公平与机会', 'zh-hant': '公平與機會', ja: '公平と機会', ko: '형평성과 기회', de: 'Gleichheit & Chancen', fr: 'Équité et possibilités', es: 'Equidad y oportunidades', ru: 'Равенство и возможности', ar: 'الإنصاف والفرص' },
