    manifestoTwo: { en: 'Responsible interpretation.', 'zh-hans': '负责任的阐释。', 'zh-hant': '負責任的闡釋。', ja: '責任ある解釈。', ko: '책임 있는 해석.', de: 'Verantwortungsvolle Interpretation.', fr: 'Une interprétation responsable.', es: 'Interpretación responsable.', ru: 'Ответственная интерпретация.', ar: 'تفسير مسؤول.' },
    heroImageAlt: { en: 'Abstract sound ripples and light in a dark field', 'zh-hans': '深色背景中的抽象声波与光线', 'zh-hant': '深色背景中的抽象聲波與光線', ja: '暗い空間に広がる抽象的な音の波紋と光', ko: '어두운 장면 속 추상적인 소리의 파동과 빛', de: 'Abstrakte Klangwellen und Licht in einem dunklen Feld', fr: 'Ondulations sonores abstraites et lumière dans un champ sombre', es: 'Ondulaciones sonoras abstractas y luz sobre un fondo oscuro', ru: 'Абстрактные звуковые волны и свет на тёмном фоне', ar: 'تموّجات صوتية وتجريدية وضوء في خلفية مظلمة' },
